def normalize_closed_nonoverlap_view(a,b,graph,label):
 nn,ee,oo,bb,ii,ss,pp=graph
 assert not oo and not bb and not ii
 spans=sorted((ea,ea+ins.size) for ea,ins in nn.items())
 assert all(y<=c for (x,y),(c,d) in zip(spans,spans[1:]))
 original=ida_bytes.get_bytes(a,b-a)
 f=ida_funcs.get_func(a);assert f is None or f.start_ea==a
 ti=ida_typeinf.tinfo_t();typed=ida_nalt.get_tinfo(ti,a)
 journal={'start':a,'end':b,'label':label,'original_bytes':original.hex(),'sha256_before':hashlib.sha256(original).hexdigest(),'old_name':ida_name.get_name(a),'old_type':str(ti) if typed else None,'old_comment':ida_funcs.get_func_cmt(f,False) if f else None,'old_chunks':list(idautils.Chunks(a)) if f else [],'patches':[]}
 if f:
  frame=ida_typeinf.tinfo_t()
  if ida_frame.get_func_frame(frame,f):journal['old_frame']={'frsize':f.frsize,'frregs':f.frregs,'fpd':f.fpd,'serialized':[v.hex() if v is not None else None for v in frame.serialize()]}
 for ea,ins in sorted(nn.items()):
  m=ins.get_canon_mnem().lower();ts=ee.get(ea,[])
  if m.startswith('j') and m!='jmp' and len(ts)==1:
   target=ts[0];raw=ida_bytes.get_bytes(ea,ins.size)
   if target==ea+ins.size:new=b'\x90'*ins.size
   elif ins.size==2:new=b'\xeb'+struct.pack('b',target-(ea+2))
   elif ins.size==6:new=b'\xe9'+struct.pack('<i',target-(ea+5))+b'\x90'
   else:raise RuntimeError('unsupported branch')
   journal['patches'].append({'ea':ea,'old':raw.hex(),'new':new.hex(),'selected':target})
 normalization_journals.append(journal)
 if f:assert ida_funcs.del_func(a)
 assert ida_bytes.del_items(a,ida_bytes.DELIT_SIMPLE,b-a)
 for p in journal['patches']:ida_bytes.patch_bytes(p['ea'],bytes.fromhex(p['new']))
 for ea,ins in sorted(nn.items()):
  n=ida_ua.create_insn(ea);assert n>0
  if ins.size==6 and n==5:assert ida_ua.create_insn(ea+5)==1
 assert ida_funcs.add_func(a,b)
 assert ida_name.set_name(a,label,ida_name.SN_CHECK)
 ida_hexrays.mark_cfunc_dirty(a)
 hf=ida_hexrays.hexrays_failure_t();cf=ida_hexrays.decompile(a,hf)
 journal['after']={'failure':hf.desc(),'failure_ea':hf.errea,'pseudocode':str(cf) if cf else None,'sha256':hashlib.sha256(ida_bytes.get_bytes(a,b-a)).hexdigest()}
 return journal
